:root {
  --bg: #1e1e2e;
  --surface: #2a2a3c;
  --text: #e0e0e0;
  --accent: #f5a623;
  --accent-hover: #ffb84d;
  --card-back: #3a3a4e;
  --card-border: #555;
  --focus: #f5a623;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  background: var(--bg);
  color: var(--text);
  min-height: 100vh;
  display: flex;
  justify-content: center;
  align-items: center;
  padding: 16px;
}

.game-container {
  background: var(--surface);
  border-radius: 16px;
  padding: 24px;
  max-width: 500px;
  width: 100%;
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.4);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 20px;
}

.game-header {
  text-align: center;
}

h1 {
  font-size: 1.5rem;
  margin-bottom: 8px;
  color: var(--accent);
}

.stats {
  font-size: 1.1rem;
}

#move-count {
  font-weight: bold;
  color: var(--accent);
}

.game-board {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 10px;
  width: 100%;
  max-width: 400px;
}

.card {
  aspect-ratio: 1 / 1;
  background: var(--card-back);
  border: 2px solid var(--card-border);
  border-radius: 10px;
  cursor: pointer;
  display: flex;
  justify-content: center;
  align-items: center;
  font-size: 1.5rem;
  font-weight: bold;
  color: transparent;
  transition: background 0.2s, transform 0.1s, border-color 0.2s;
  user-select: none;
  position: relative;
}

.card:hover {
  border-color: var(--accent);
  transform: scale(1.03);
}

.card:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}

.card.flipped {
  background: var(--accent);
  border-color: var(--accent);
  color: var(--bg);
  transform: scale(1);
}

.card.matched {
  background: #4caf50;
  border-color: #4caf50;
  color: #fff;
  cursor: default;
  transform: scale(1);
}

.card.matched:hover {
  transform: scale(1);
  border-color: #4caf50;
}

.win-message {
  font-size: 1.3rem;
  font-weight: bold;
  color: var(--accent);
  text-align: center;
  padding: 8px;
}

.new-game-btn {
  background: var(--accent);
  color: var(--bg);
  border: none;
  border-radius: 8px;
  padding: 12px 32px;
  font-size: 1.1rem;
  font-weight: bold;
  cursor: pointer;
  transition: background 0.2s, transform 0.1s;
}

.new-game-btn:hover {
  background: var(--accent-hover);
}

.new-game-btn:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}

.new-game-btn:active {
  transform: scale(0.97);
}

@media (max-width: 400px) {
  .game-container {
    padding: 16px;
  }
  .game-board {
    gap: 6px;
  }
  h1 {
    font-size: 1.3rem;
  }
}

[hidden] {
  display: none !important;
}

const COLORS = [
  '#e74c3c', '#3498db', '#2ecc71', '#f1c40f',
  '#9b59b6', '#e67e22', '#1abc9c', '#e84393'
];

const board = document.getElementById('game-board');
const moveCountEl = document.getElementById('move-count');
const winMessage = document.getElementById('win-message');
const newGameBtn = document.getElementById('new-game');

let deck = [];
let flippedCards = [];
let matchedPairs = 0;
let moves = 0;
let lockBoard = false;

function shuffle(array) {
  for (let i = array.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [array[i], array[j]] = [array[j], array[i]];
  }
  return array;
}

function createDeck() {
  const cards = [];
  COLORS.forEach((color, index) => {
    cards.push({ id: index, color });
    cards.push({ id: index, color });
  });
  return shuffle(cards);
}

function renderBoard() {
  board.innerHTML = '';
  deck.forEach((card, index) => {
    const cardEl = document.createElement('button');
    cardEl.type = 'button';
    cardEl.className = 'card';
    cardEl.dataset.index = index;
    cardEl.dataset.id = card.id;
    cardEl.dataset.color = card.color;
    cardEl.setAttribute('aria-label', 'Card ' + (index + 1) + ', hidden');
    cardEl.addEventListener('click', handleCardClick);
    board.appendChild(cardEl);
  });
}

function handleCardClick(e) {
  const card = e.currentTarget;
  if (lockBoard || card.classList.contains('flipped') || card.classList.contains('matched')) return;

  flipCard(card);
  flippedCards.push(card);

  if (flippedCards.length === 2) {
    moves++;
    moveCountEl.textContent = moves;
    checkMatch();
  }
}

function flipCard(card) {
  card.classList.add('flipped');
  card.style.background = card.dataset.color;
  card.style.borderColor = card.dataset.color;
  card.textContent = '★';
  card.setAttribute('aria-label', 'Card ' + (parseInt(card.dataset.index) + 1) + ', revealed');
}

function checkMatch() {
  const [card1, card2] = flippedCards;
  if (card1.dataset.id === card2.dataset.id) {
    card1.classList.add('matched');
    card2.classList.add('matched');
    card1.setAttribute('aria-label', 'Card ' + (parseInt(card1.dataset.index) + 1) + ', matched');
    card2.setAttribute('aria-label', 'Card ' + (parseInt(card2.dataset.index) + 1) + ', matched');
    matchedPairs++;
    flippedCards = [];
    if (matchedPairs === COLORS.length) {
      winMessage.hidden = false;
    }
  } else {
    lockBoard = true;
    setTimeout(() => {
      card1.classList.remove('flipped');
      card2.classList.remove('flipped');
      card1.style.background = '';
      card2.style.background = '';
      card1.style.borderColor = '';
      card2.style.borderColor = '';
      card1.textContent = '';
      card2.textContent = '';
      card1.setAttribute('aria-label', 'Card ' + (parseInt(card1.dataset.index) + 1) + ', hidden');
      card2.setAttribute('aria-label', 'Card ' + (parseInt(card2.dataset.index) + 1) + ', hidden');
      flippedCards = [];
      lockBoard = false;
    }, 800);
  }
}

function resetGame() {
  deck = createDeck();
  flippedCards = [];
  matchedPairs = 0;
  moves = 0;
  lockBoard = false;
  moveCountEl.textContent = '0';
  winMessage.hidden = true;
  renderBoard();
}

newGameBtn.addEventListener('click', resetGame);

resetGame();
